s = sys.stdin.read().strip()
m = re.fullmatch(r'([^{}]*)\{([^{}]*)\}([^{}]*)', s)
if m:
    toks = m.group(2).split(',')
    if len(toks) >= 2:
        for t in toks:
            print(m.group(1) + t + m.group(3))
    else:
        print(s)
else:
    print(s)

